import React, { useRef } from 'react';

// Create the App component here
const App = () => {
  // Create your typed DOM ref here
  const inputRef = useRef<HTMLInputElement>(null);

  // Define CustomObject interface and create typed custom object ref here
  interface CustomObject {
    value: string;
  }
  const customRef = useRef<CustomObject>({ value: 'initial' });

  // Create handler to focus input using ref
  const focusInput = () => {
    inputRef.current?.focus();
  };

  // Create handler to update custom object ref
  const updateCustomRef = () => {
    customRef.current.value = 'updated';
  };

  return (
    <>
      {/* Add input element with ref here */}
      <input ref={inputRef} type="text" />
      {/* Add button to focus input here */}
      <button onClick={focusInput}>Focus Input</button>
      {/* Add button to update custom ref here */}
      <button onClick={updateCustomRef}>Update Custom Ref</button>
      {/* Add paragraph to display custom ref value here */}
    </>
  );
};

